{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Practical habits, memorable frameworks, and guided cohorts to make well-being manageable in {{CITY}}, {{STATE}}." />
  <link rel="stylesheet" href="assets/css/styles.css" />
  <script defer src="assets/js/main.js"></script>
</head>
<body class="layout-asym">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav aria-label="Primary navigation">
        <ul class="nav">
          <li><a href="/">Nest</a></li>
          <li><a href="about.html">My Approach</a></li>
          <li><a href="programs.html">Programs</a></li>
          <li><a href="services.html">Sessions</a></li>
          <li><a href="pricing.html">Investment</a></li>
          <li><a href="testimonials.html">Stories</a></li>
          <li><a class="cta" href="book.html">{{PRIMARY_CTA_LABEL}}</a></li>
        </ul>
      </nav>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero" id="hero">
      <div class="wrap hero-grid">
        <div class="hero-copy">
          <h1>Craft a week that feels like you—without extra willpower.</h1>
          <p class="lede">Tidy habits, repeatable sessions, and a cohort-backed rhythm to help you move toward brighter, calmer days in {{CITY}}, {{STATE}}.</p>
          <p class="meta">Cohort model: small groups, guided lessons, weekly check-ins.</p>
          <p class="actions">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="programs.html">See cohorts</a>
          </p>
        </div>
        <div class="hero-visual">
          <svg class="pattern" viewBox="0 0 400 320" aria-hidden="true">
            <defs>
              <pattern id="p" width="40" height="40" patternUnits="userSpaceOnUse">
                <rect width="40" height="40" fill="#fff" />
                <circle cx="20" cy="20" r="6" fill="rgba(96, 165, 250, 0.12)" />
              </pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#p)" />
            <g transform="translate(40,20)" fill="none" stroke="#60a5fa" stroke-width="2">
              <path d="M0 40 C30 0, 90 0, 120 40"/>
              <path d="M80 100 C110 60, 170 60, 200 100"/>
            </g>
          </svg>
          <div class="card-cta">
            <strong>Try the Session Planner</strong>
            <p>Create a personalized session in seconds — exportable as plain text.</p>
            <button class="btn" id="open-planner">Open planner</button>
          </div>
        </div>
      </div>
    </section>

    <!-- FRAMEWORK (moved early) -->
    <section class="framework" id="framework">
      <div class="wrap">
        <h2>Three anchors that make progress repeatable</h2>
        <div class="frames">
          <article>
            <h3>Anchor 1: Micro-Rituals</h3>
            <p>Short, clear actions you can actually do every day. No radical schedule changes—just reliable nudges that stack up.</p>
          </article>
          <article>
            <h3>Anchor 2: Focused Sessions</h3>
            <p>A blueprint for 30–60 minute sessions that blend coaching prompts, habits, and reflection so you leave with a next step.</p>
          </article>
          <article>
            <h3>Anchor 3: Cohort Support</h3>
            <p>Weekly shared learning where progress is social, practical, and tracked.</p>
          </article>
        </div>
      </div>
    </section>

    <!-- STORY -->
    <section class="story" id="story">
      <div class="wrap story-grid">
        <div class="story-text">
          <h2>Why this works</h2>
          <p>I pair evidence-informed habit design with a pragmatic session structure so you leave each week with a small, tangible win. This isn't therapy or medical care—it's coaching that helps you build everyday practices that matter.</p>
          <p class="muted">Local cohorts, flexible pacing, and tools that fit real life.</p>
        </div>
        <div class="story-quote">
          <blockquote>"I learned how to plan a week that actually happens. Less friction, more calm." — participant</blockquote>
        </div>
      </div>
    </section>

    <!-- OFFERS -->
    <section class="offers" id="offers">
      <div class="wrap">
        <h2>Offerings</h2>
        <div class="offer-grid">
          <div class="offer">
            <h3>Starter Sprint</h3>
            <p>4-week cohort designed to create a daily habit loop and a weekly session routine.</p>
            <p class="price">From $199</p>
            <p><a href="programs.html" class="btn">Join next cohort</a></p>
          </div>
          <div class="offer">
            <h3>Deep Habit Lab</h3>
            <p>8 weeks of structured practice with individual check-ins and habit engineering workshops.</p>
            <p class="price">From $499</p>
            <p><a href="programs.html" class="btn">Apply</a></p>
          </div>
          <div class="offer">
            <h3>Session Bundle</h3>
            <p>6 one-on-one sessions to build a personalized roadmap and weekly rituals.</p>
            <p class="price">$799</p>
            <p><a href="services.html" class="btn">Book a consult</a></p>
          </div>
        </div>
      </div>
    </section>

    <!-- SESSION PLANNER WIDGET -->
    <section class="planner" id="planner">
      <div class="wrap">
        <h2>Session Planner</h2>
        <p>Design a focused session: choose goals, micro-habits, and a follow-up action. Export a plain-text summary to share or save.</p>
        <div class="planner-grid">
          <form id="planner-form">
            <label>Participant name
              <input type="text" id="p-name" placeholder="Your name" />
            </label>
            <label>Primary focus
              <select id="p-focus">
                <option>Energy & Sleep</option>
                <option>Stress & Boundaries</option>
                <option>Movement & Momentum</option>
                <option>Nutrition & Rhythm</option>
                <option>Custom</option>
              </select>
            </label>
            <label>Top 3 session goals (comma separated)
              <input type="text" id="p-goals" placeholder="clarify priority, choose 1 small habit, set a follow-up" />
            </label>
            <label>Micro-habit to practice
              <input type="text" id="p-habit" placeholder="e.g., 5-min morning breathing" />
            </label>
            <label>Follow-up checkpoint (when?)
              <input type="text" id="p-check" placeholder="e.g., 3 days after session" />
            </label>
            <div class="planner-actions">
              <button type="button" class="btn" id="build-session">Build plan</button>
              <button type="button" class="btn ghost" id="copy-session">Copy summary</button>
            </div>
          </form>

          <div class="planner-preview" aria-live="polite">
            <h3>Preview</h3>
            <pre id="session-output" tabindex="0">Your session summary will appear here.</pre>
          </div>
        </div>
      </div>
    </section>

    <!-- HABIT BUILDER -->
    <section class="habit" id="habit">
      <div class="wrap">
        <h2>7-Day Challenge Generator</h2>
        <p>Create a simple 7-day plan and print a checklist to carry with you.</p>
        <form id="habit-form" class="habit-form">
          <label>Challenge name
            <input type="text" id="habit-name" placeholder="e.g., 7-Day Evening Calm" />
          </label>
          <label>Daily micro-action
            <input type="text" id="habit-action" placeholder="e.g., 3-minute wind-down" />
          </label>
          <label>Level
            <select id="habit-level">
              <option>Easy (1-3 mins)</option>
              <option>Moderate (4-6 mins)</option>
              <option>Bold (7-10 mins)</option>
            </select>
          </label>
          <div class="habit-actions">
            <button type="button" class="btn" id="generate-challenge">Generate checklist</button>
            <button type="button" class="btn ghost" id="print-checklist">Print</button>
          </div>
        </form>

        <div class="habit-preview">
          <h3 id="habit-title">Your 7-day checklist</h3>
          <ol id="habit-list" class="checklist">
            <li>Use the generator to fill this in.</li>
          </ol>
        </div>
      </div>
    </section>

    <!-- TESTIMONIALS -->
    <section class="testimonials" id="testimonials">
      <div class="wrap">
        <h2>Stories from the cohort</h2>
        <div class="test-grid">
          <figure>
            <blockquote>"A practical framework that actually fit into my week."</blockquote>
            <figcaption>— R., participant</figcaption>
          </figure>
          <figure>
            <blockquote>"The cohort gave me structure and small steps I could keep."</blockquote>
            <figcaption>— S., participant</figcaption>
          </figure>
          <figure>
            <blockquote>"I sleep better and I notice the small wins stacking up."</blockquote>
            <figcaption>— T., participant</figcaption>
          </figure>
        </div>
      </div>
    </section>

    <!-- PRICING (moved later) -->
    <section class="pricing" id="pricing">
      <div class="wrap">
        <h2>Investment</h2>
        <p>Simple tiers designed around commitment, not gimmicks. Choose what fits your rhythm.</p>
        <div class="pricing-grid">
          <div class="tier">
            <h3>Starter</h3>
            <p>Core cohort + templates</p>
            <p class="price">$199</p>
          </div>
          <div class="tier featured">
            <h3>Growth</h3>
            <p>8-week lab + group coaching</p>
            <p class="price">$499</p>
          </div>
          <div class="tier">
            <h3>Short Course</h3>
            <p>One-off session bundle</p>
            <p class="price">$799</p>
          </div>
        </div>
      </div>
    </section>

    <!-- CTA -->
    <section class="final-cta" id="final-cta">
      <div class="wrap cta-grid">
        <div>
          <h2>Ready to make your next week matter?</h2>
          <p>Join a small cohort and get a weekly session plan delivered to your inbox.</p>
        </div>
        <div>
          <a class="btn primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <p class="muted">Or call <a href="tel:{{PHONE}}">{{PHONE}}</a> to ask a question.</p>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap foot-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p>{{TAGLINE}}</p>
      </div>
      <nav>
        <ul>
          <li><a href="about.html">About</a></li>
          <li><a href="contact.html">Contact</a></li>
          <li><a href="book.html">Book</a></li>
        </ul>
      </nav>
      <div class="contact">
        <p><a href="tel:{{PHONE}}">{{PHONE}}</a></p>
        <p><a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
    </div>
    <svg class="bg-pattern" role="img" aria-hidden="true">
      <use href="assets/img/pattern.svg#tile" />
    </svg>
  </footer>
</body>
</html>"} 
