{"path":"assets/css/styles.css","content":"/* Core styles for the wellness coach template */
:root{
  --bg:#fbfdff;
  --muted:#6b7280;
  --accent:#60a5fa;
  --accent-2:#7c3aed;
  --text:#0f172a;
  --card:#ffffff;
  --radius:12px;
  --max:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:var(--text);background:var(--bg);-webkit-font-smoothing:antialiased}
.wrap{max-width:var(--max);margin:0 auto;padding:2rem}
.site-header{background:linear-gradient(180deg,rgba(96,165,250,0.06),transparent);border-bottom:1px solid rgba(15,23,42,0.04)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;color:var(--text);text-decoration:none}
.nav{list-style:none;margin:0;padding:0;display:flex;gap:0.5rem}
.nav a{color:var(--text);text-decoration:none;padding:0.5rem 0.75rem;border-radius:8px}
.nav a.cta{background:var(--accent);color:#fff}
.hero{padding:3rem 0 2rem}
.hero-grid{display:grid;grid-template-columns:1fr 340px;gap:2rem;align-items:center}
.hero h1{font-size:clamp(1.6rem,3vw,2.4rem);margin:0}
.lede{color:var(--muted);margin-top:.5rem}
.meta{font-size:.9rem;color:var(--muted);margin-top:.75rem}
.btn{display:inline-block;padding:.6rem 1rem;border-radius:10px;border:1px solid rgba(15,23,42,0.06);background:var(--card);cursor:pointer}
.btn.primary{background:var(--accent);color:#fff;border:none}
.btn.ghost{background:transparent;border:1px solid rgba(15,23,42,0.08)}
.hero-visual{position:relative;background:linear-gradient(180deg,#fff,#f8fbff);padding:1.25rem;border-radius:var(--radius);box-shadow:0 6px 20px rgba(2,6,23,0.06)}
.pattern{width:100%;height:160px;display:block}
.card-cta{position:absolute;right:1rem;bottom:1rem;background:linear-gradient(90deg,rgba(96,165,250,0.06),rgba(124,58,237,0.04));padding:1rem;border-radius:10px}
.framework{padding:2rem 0}
.frames{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem;margin-top:1rem}
.frames article{background:var(--card);padding:1rem;border-radius:12px;box-shadow:0 4px 14px rgba(2,6,23,0.04)}
.story{padding:2rem 0}
.story-grid{display:grid;grid-template-columns:1fr 320px;gap:1.5rem}
.story-quote blockquote{font-style:italic;background:linear-gradient(90deg,#fff,#f7fbff);padding:1rem;border-radius:10px}
.offers{padding:2rem 0}
.offer-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem}
.offer{background:var(--card);padding:1rem;border-radius:10px}
.price{font-weight:700;color:var(--accent);margin-top:.5rem}
.planner{padding:2rem 0;background:linear-gradient(180deg,transparent,#fff9)}
.planner-grid{display:grid;grid-template-columns:360px 1fr;gap:1rem;align-items:start}
#planner-form label{display:block;margin-bottom:.6rem;font-size:.9rem;color:var(--muted)}
#planner-form input,#planner-form select{width:100%;padding:.6rem;border-radius:8px;border:1px solid rgba(15,23,42,0.06);margin-top:.25rem}
.planner-preview{background:var(--card);padding:1rem;border-radius:10px;min-height:220px}
.planner-preview pre{white-space:pre-wrap;background:transparent;border:none;padding:0;margin:0;font-family:inherit;outline:none}
.habit{padding:2rem 0}
.habit-form{display:flex;gap:1rem;align-items:flex-end}
.habit-form label{flex:1}
.habit-actions{display:flex;gap:.5rem}
.habit-preview{margin-top:1rem}
.checklist{background:var(--card);padding:1rem;border-radius:12px}
.testimonials{padding:2rem 0}
.test-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem}
.test-grid figure{background:var(--card);padding:1rem;border-radius:10px}
.pricing{padding:2rem 0}
.pricing-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem}
.tier{background:var(--card);padding:1rem;border-radius:10px}
.tier.featured{border:2px solid var(--accent);transform:translateY(-6px)}
.final-cta{padding:2rem 0;background:linear-gradient(90deg,rgba(124,58,237,0.05),transparent)}
.cta-grid{display:flex;justify-content:space-between;align-items:center}
.site-footer{border-top:1px solid rgba(15,23,42,0.04);padding:1.5rem 0;background:#fff}
.foot-grid{display:grid;grid-template-columns:1fr auto auto;gap:1rem;align-items:center}
.bg-pattern{position:absolute;width:0;height:0}
@media (max-width:900px){
  .hero-grid,.story-grid,.frames, .offer-grid,.test-grid,.pricing-grid{grid-template-columns:1fr}
  .planner-grid{grid-template-columns:1fr}
  .wrap{padding:1rem}
}
/* Print styles for checklist */
@media print{
  body *{visibility:hidden}
  .print-area, .print-area *{visibility:visible}
  .print-area{position:fixed;left:0;top:0}
}"} 
{"path":"assets/js/main.js","content":"// Session planner and 7-day habit generator
document.addEventListener('DOMContentLoaded',function(){
  // Planner elements
  const nameInput=document.getElementById('p-name');
  const focusInput=document.getElementById('p-focus');
  const goalsInput=document.getElementById('p-goals');
  const habitInput=document.getElementById('p-habit');
  const checkInput=document.getElementById('p-check');
  const buildBtn=document.getElementById('build-session');
  const copyBtn=document.getElementById('copy-session');
  const output=document.getElementById('session-output');

  function buildSummary(){
    const who=nameInput.value.trim()||'Participant';
    const focus=focusInput.value;
    const goals=goalsInput.value.trim()||'Clarify one priority, choose a micro-habit, set a checkpoint.';
    const habit=habitInput.value.trim()||'Short habit of choice';
    const check=checkInput.value.trim()||'Check-in in 3 days';

    const date=new Date().toLocaleDateString();
    const summary=[
      `Session summary — ${date}`,
      `Name: ${who}`,
      `Focus area: ${focus}`,
      `3 goals: ${goals}`,
      `Micro-habit: ${habit}`,
      `Follow-up: ${check}`,
      '',
      'Session structure:',
      '- 5 min: arrival & context',
      '- 15-30 min: coaching prompts & practice',
      '- 5-10 min: commit to micro-habit & plan next check-in',
      '',
      'Next steps:',
      `- Try the micro-habit for 7 days`,
      `- Note wins and barriers for the follow-up (${check})`
    ].join('\n');

    output.textContent=summary;
    return summary;
  }

  buildBtn.addEventListener('click',function(){
    buildSummary();
    output.focus();
  });

  copyBtn.addEventListener('click',function(){
    const text=output.textContent;
    if(!text) return;
    navigator.clipboard.writeText(text).then(()=>{
      copyBtn.textContent='Copied!';
      setTimeout(()=>copyBtn.textContent='Copy summary',1200);
    }).catch(()=>{
      // fallback
      const ta=document.createElement('textarea');ta.value=text;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();
      copyBtn.textContent='Copied!';setTimeout(()=>copyBtn.textContent='Copy summary',1200);
    });
  });

  // Habit builder
  const habitName=document.getElementById('habit-name');
  const habitAction=document.getElementById('habit-action');
  const habitLevel=document.getElementById('habit-level');
  const generateBtn=document.getElementById('generate-challenge');
  const printBtn=document.getElementById('print-checklist');
  const habitTitle=document.getElementById('habit-title');
  const habitList=document.getElementById('habit-list');

  function generateChecklist(){
    const name=habitName.value.trim()||'7-Day Challenge';
    const action=habitAction.value.trim()||'Micro-action of choice';
    const level=habitLevel.value;
    habitTitle.textContent=`${name} — ${level}`;
    // Build 7 entries with slight progress hints
    habitList.innerHTML='';
    for(let i=1;i<=7;i++){
      const li=document.createElement('li');
      li.textContent=`Day ${i}: ${action} (${i===7? 'Reflection day — note progress & tweak':'Do it — track time & ease'})`;
      habitList.appendChild(li);
    }
    // make checklist printable by copying into a print-area
    ensurePrintArea();
  }

  function ensurePrintArea(){
    let printArea=document.querySelector('.print-area');
    if(!printArea){
      printArea=document.createElement('div');
      printArea.className='print-area';
      document.body.appendChild(printArea);
    }
    printArea.innerHTML=`<h1>${habitTitle.textContent}</h1><ol>${Array.from(habitList.children).map(li=>`<li>${li.textContent}</li>`).join('')}</ol>`;
  }

  generateBtn.addEventListener('click',function(){
    generateChecklist();
  });

  printBtn.addEventListener('click',function(){
    ensurePrintArea();
    window.print();
  });

  // Quick open planner from hero
  const openPlanner=document.getElementById('open-planner');
  if(openPlanner){
    openPlanner.addEventListener('click',function(){
      document.getElementById('planner').scrollIntoView({behavior:'smooth',block:'center'});
      nameInput.focus();
    });
  }

});"} 
